using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Constructor_SetsPageIndex()
        {
            var items = new List<string> { "a", "b" };

            var list = new PaginatedList<string>(items, 10, 2, 3);

            Assert.Equal(2, list.PageIndex);
        }

        [Fact]
        public void Constructor_CalculatesTotalPages()
        {
            var items = new List<string> { "a", "b", "c" };

            var list = new PaginatedList<string>(items, 10, 1, 3);

            Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
        }

        [Fact]
        public void Constructor_AddsItemsToList()
        {
            var items = new List<string> { "a", "b", "c" };

            var list = new PaginatedList<string>(items, 10, 1, 3);

            Assert.Equal(3, list.Count);
            Assert.Contains("a", list);
            Assert.Contains("b", list);
            Assert.Contains("c", list);
        }

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            var list = new PaginatedList<string>(new List<string>(), 10, 1, 3);

            Assert.False(list.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            var list = new PaginatedList<string>(new List<string>(), 10, 2, 3);

            Assert.True(list.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            var list = new PaginatedList<string>(new List<string>(), 10, 4, 3);

            Assert.False(list.HasNextPage);
        }

        [Fact]
        public void HasNextPage_FirstPage_ReturnsTrue()
        {
            var list = new PaginatedList<string>(new List<string>(), 10, 1, 3);

            Assert.True(list.HasNextPage);
        }

        [Fact]
        public void Create_ReturnsCorrectPage()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();

            var list = PaginatedList<int>.Create(source, 2, 5);

            Assert.Equal(5, list.Count);
            Assert.Equal(6, list.First());
            Assert.Equal(10, list.Last());
        }

        [Fact]
        public void Create_SetsCorrectPageIndex()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();

            var list = PaginatedList<int>.Create(source, 3, 5);

            Assert.Equal(3, list.PageIndex);
        }

        [Fact]
        public void Create_SetsCorrectTotalPages()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();

            var list = PaginatedList<int>.Create(source, 1, 5);

            Assert.Equal(4, list.TotalPages);
        }

        [Fact]
        public void Create_SinglePage_NoNextOrPrevious()
        {
            var source = Enumerable.Range(1, 3).AsQueryable();

            var list = PaginatedList<int>.Create(source, 1, 10);

            Assert.False(list.HasPreviousPage);
            Assert.False(list.HasNextPage);
            Assert.Equal(1, list.TotalPages);
        }

        [Fact]
        public void TotalPages_ExactDivision()
        {
            var list = new PaginatedList<int>(new List<int>(), 10, 1, 5);

            Assert.Equal(2, list.TotalPages);
        }

        [Fact]
        public void TotalPages_WithRemainder()
        {
            var list = new PaginatedList<int>(new List<int>(), 11, 1, 5);

            Assert.Equal(3, list.TotalPages); // ceil(11/5) = 3
        }
    }
}

