using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests : IDisposable
    {
        private readonly SchoolContext _context;

        public DbInitializerTests()
        {
            _context = TestHelpers.CreateInMemoryContext();
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        [Fact]
        public void Initialize_SeedsStudents()
        {
            DbInitializer.Initialize(_context);

            Assert.Equal(8, _context.Students.Count());
        }

        [Fact]
        public void Initialize_SeedsInstructors()
        {
            DbInitializer.Initialize(_context);

            Assert.Equal(5, _context.Instructors.Count());
        }

        [Fact]
        public void Initialize_SeedsDepartments()
        {
            DbInitializer.Initialize(_context);

            Assert.Equal(4, _context.Departments.Count());
        }

        [Fact]
        public void Initialize_SeedsCourses()
        {
            DbInitializer.Initialize(_context);

            Assert.Equal(7, _context.Courses.Count());
        }

        [Fact]
        public void Initialize_SeedsEnrollments()
        {
            DbInitializer.Initialize(_context);

            Assert.Equal(11, _context.Enrollments.Count());
        }

        [Fact]
        public void Initialize_SeedsOfficeAssignments()
        {
            DbInitializer.Initialize(_context);

            Assert.Equal(3, _context.OfficeAssignments.Count());
        }

        [Fact]
        public void Initialize_SeedsCourseAssignments()
        {
            DbInitializer.Initialize(_context);

            Assert.Equal(8, _context.CourseAssignments.Count());
        }

        [Fact]
        public void Initialize_CalledTwice_DoesNotDuplicate()
        {
            DbInitializer.Initialize(_context);
            DbInitializer.Initialize(_context);

            Assert.Equal(8, _context.Students.Count());
        }

        [Fact]
        public void Initialize_SetsStudentNames()
        {
            DbInitializer.Initialize(_context);

            var alexander = _context.Students.First(s => s.LastName == "Alexander");
            Assert.Equal("Carson", alexander.FirstMidName);
        }

        [Fact]
        public void Initialize_SetsEnrollmentGrades()
        {
            DbInitializer.Initialize(_context);

            var enrollmentsWithGrades = _context.Enrollments.Where(e => e.Grade != null).ToList();
            Assert.True(enrollmentsWithGrades.Count > 0);
        }

        [Fact]
        public void Initialize_SetsEnrollmentsWithNoGrade()
        {
            DbInitializer.Initialize(_context);

            var enrollmentsWithoutGrades = _context.Enrollments.Where(e => e.Grade == null).ToList();
            Assert.Single(enrollmentsWithoutGrades);
        }
    }

    public class SchoolContextTests : IDisposable
    {
        private readonly SchoolContext _context;

        public SchoolContextTests()
        {
            _context = TestHelpers.CreateInMemoryContext();
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        [Fact]
        public void Context_HasStudentsDbSet()
        {
            Assert.NotNull(_context.Students);
        }

        [Fact]
        public void Context_HasCoursesDbSet()
        {
            Assert.NotNull(_context.Courses);
        }

        [Fact]
        public void Context_HasDepartmentsDbSet()
        {
            Assert.NotNull(_context.Departments);
        }

        [Fact]
        public void Context_HasEnrollmentsDbSet()
        {
            Assert.NotNull(_context.Enrollments);
        }

        [Fact]
        public void Context_HasInstructorsDbSet()
        {
            Assert.NotNull(_context.Instructors);
        }

        [Fact]
        public void Context_HasCourseAssignmentsDbSet()
        {
            Assert.NotNull(_context.CourseAssignments);
        }

        [Fact]
        public void Context_HasOfficeAssignmentsDbSet()
        {
            Assert.NotNull(_context.OfficeAssignments);
        }

        [Fact]
        public void Context_HasNotificationsDbSet()
        {
            Assert.NotNull(_context.Notifications);
        }

        [Fact]
        public void Context_HasPeopleDbSet()
        {
            Assert.NotNull(_context.People);
        }

        [Fact]
        public void Context_CanAddAndRetrieveStudent()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "User",
                EnrollmentDate = DateTime.Parse("2020-09-01")
            };

            _context.Students.Add(student);
            _context.SaveChanges();

            var retrieved = _context.Students.Find(student.ID);
            Assert.NotNull(retrieved);
            Assert.Equal("Test", retrieved.FirstMidName);
        }

        [Fact]
        public void Context_CourseAssignment_CompositeKey()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Prof",
                HireDate = DateTime.Parse("2020-01-01")
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var dept = new Department { Name = "Test", Budget = 100, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 9999, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var assignment = new CourseAssignment
            {
                InstructorID = instructor.ID,
                CourseID = course.CourseID
            };
            _context.CourseAssignments.Add(assignment);
            _context.SaveChanges();

            var retrieved = _context.CourseAssignments.Find(course.CourseID, instructor.ID);
            Assert.NotNull(retrieved);
        }

        [Fact]
        public void Context_CanAddNotification()
        {
            var notification = new Notification
            {
                EntityType = "Test",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test",
                CreatedAt = DateTime.Now,
                CreatedBy = "System",
                IsRead = false
            };

            _context.Notifications.Add(notification);
            _context.SaveChanges();

            Assert.Equal(1, _context.Notifications.Count());
        }
    }
}

