            _service.ReceiveNotification();
            DrainQueue();
            var secondRead = _service.ReceiveNotification();

            Assert.Null(secondRead);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            var exception = Record.Exception(() => _service.MarkAsRead(999));

            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();

            var exception = Record.Exception(() => service.Dispose());

            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_TwoParamOverload_Works()
        {
            var notification = SendAndReceive("Student", "1", EntityOperation.CREATE);

            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
        }

        [Fact]
        public void SendNotification_NullDisplayName_UsesIdFallback()
        {
            DrainQueue();
            _service.SendNotification("Student", "5", null, EntityOperation.UPDATE);
            var notification = _service.ReceiveNotification();

            Assert.Contains("5", notification.Message);
        }

        [Fact]
        public void SendNotification_EmptyDisplayName_UsesIdFallback()
        {
            DrainQueue();
            _service.SendNotification("Student", "5", "  ", EntityOperation.UPDATE);
            var notification = _service.ReceiveNotification();

            Assert.Contains("5", notification.Message);
        }
    }
}

